-- TEMPORAL.md normative examples as result assertions (java.time reference).
-- Uniform-rendering subset: distances + end functions render identically across
-- dialects. Clamping (month_add) and begin (month_begin) are deferred until the
-- DATE->TIMESTAMP type promotion (task #22) is fixed, since their rendering diverges.
SELECT
  (CASE WHEN ((CAST(strftime('%Y', '2023-03-31') AS INTEGER) * 12 + CAST(strftime('%m', '2023-03-31') AS INTEGER)) - (CAST(strftime('%Y', '2023-01-31') AS INTEGER) * 12 + CAST(strftime('%m', '2023-01-31') AS INTEGER))) > 0 AND CAST(strftime('%d', '2023-03-31') AS INTEGER) < CAST(strftime('%d', '2023-01-31') AS INTEGER) THEN ((CAST(strftime('%Y', '2023-03-31') AS INTEGER) * 12 + CAST(strftime('%m', '2023-03-31') AS INTEGER)) - (CAST(strftime('%Y', '2023-01-31') AS INTEGER) * 12 + CAST(strftime('%m', '2023-01-31') AS INTEGER))) - 1 WHEN ((CAST(strftime('%Y', '2023-03-31') AS INTEGER) * 12 + CAST(strftime('%m', '2023-03-31') AS INTEGER)) - (CAST(strftime('%Y', '2023-01-31') AS INTEGER) * 12 + CAST(strftime('%m', '2023-01-31') AS INTEGER))) < 0 AND CAST(strftime('%d', '2023-03-31') AS INTEGER) > CAST(strftime('%d', '2023-01-31') AS INTEGER) THEN ((CAST(strftime('%Y', '2023-03-31') AS INTEGER) * 12 + CAST(strftime('%m', '2023-03-31') AS INTEGER)) - (CAST(strftime('%Y', '2023-01-31') AS INTEGER) * 12 + CAST(strftime('%m', '2023-01-31') AS INTEGER))) + 1 ELSE ((CAST(strftime('%Y', '2023-03-31') AS INTEGER) * 12 + CAST(strftime('%m', '2023-03-31') AS INTEGER)) - (CAST(strftime('%Y', '2023-01-31') AS INTEGER) * 12 + CAST(strftime('%m', '2023-01-31') AS INTEGER))) END) AS whole_two
, (CASE WHEN ((CAST(strftime('%Y', '2023-03-30') AS INTEGER) * 12 + CAST(strftime('%m', '2023-03-30') AS INTEGER)) - (CAST(strftime('%Y', '2023-01-31') AS INTEGER) * 12 + CAST(strftime('%m', '2023-01-31') AS INTEGER))) > 0 AND CAST(strftime('%d', '2023-03-30') AS INTEGER) < CAST(strftime('%d', '2023-01-31') AS INTEGER) THEN ((CAST(strftime('%Y', '2023-03-30') AS INTEGER) * 12 + CAST(strftime('%m', '2023-03-30') AS INTEGER)) - (CAST(strftime('%Y', '2023-01-31') AS INTEGER) * 12 + CAST(strftime('%m', '2023-01-31') AS INTEGER))) - 1 WHEN ((CAST(strftime('%Y', '2023-03-30') AS INTEGER) * 12 + CAST(strftime('%m', '2023-03-30') AS INTEGER)) - (CAST(strftime('%Y', '2023-01-31') AS INTEGER) * 12 + CAST(strftime('%m', '2023-01-31') AS INTEGER))) < 0 AND CAST(strftime('%d', '2023-03-30') AS INTEGER) > CAST(strftime('%d', '2023-01-31') AS INTEGER) THEN ((CAST(strftime('%Y', '2023-03-30') AS INTEGER) * 12 + CAST(strftime('%m', '2023-03-30') AS INTEGER)) - (CAST(strftime('%Y', '2023-01-31') AS INTEGER) * 12 + CAST(strftime('%m', '2023-01-31') AS INTEGER))) + 1 ELSE ((CAST(strftime('%Y', '2023-03-30') AS INTEGER) * 12 + CAST(strftime('%m', '2023-03-30') AS INTEGER)) - (CAST(strftime('%Y', '2023-01-31') AS INTEGER) * 12 + CAST(strftime('%m', '2023-01-31') AS INTEGER))) END) AS not_complete_one
, CAST(julianday('2023-02-01') - julianday('2023-03-01') AS INTEGER) AS signed_minus28
, date('2024-02-10', 'start of month', '+1 month', '-1 day') AS end_leap
, date('2024-05-20', 'start of month', printf('%+d months', 3 - ((CAST(strftime('%m', '2024-05-20') AS INTEGER) - 1) % 3)), '-1 day') AS end_q2
, date('2024-05-20', 'start of year', '+1 year', '-1 day') AS end_year
FROM
 check_temporal c